<script setup lang="ts">import{ref}from'vue';import{ElMessage,ElMessageBox,type UploadFile}from'element-plus';import{api}from'../api/admin';const file=ref<File|null>(null),loading=ref(false),result=ref<any>();function change(f:UploadFile){file.value=f.raw||null;result.value=null}async function preview(){if(!file.value)return ElMessage.warning('请选择甲方对账文件');const data=new FormData();data.append('file',file.value);loading.value=true;try{result.value=await api.reconciliationPreview(data);ElMessage.success('解析完成，请核对后再确认导入')}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}async function confirm(){try{await ElMessageBox.confirm('确认后将依据匹配结果更新正式订单状态，未唯一匹配的数据不会被覆盖。','确认导入',{type:'warning'});await api.reconciliationConfirm(result.value.batch.id);ElMessage.success('对账数据已确认导入');result.value.batch.status='CONFIRMED'}catch(e:any){if(e!=='cancel'&&e!=='close'&&e?.message)ElMessage.error(e.message)}}</script>
<template><div class="page"><div class="page-heading"><div><h1>甲方文件导入</h1><p>上传 CMHK 对账数据，先解析预览，再确认更新订单。</p></div></div><div class="table-card" style="padding:24px"><div class="hint-box">匹配优先级：UMALL订单号 → ICCID → 手机号。无法唯一匹配的数据会进入异常列表。</div><el-upload drag :auto-upload="false" :limit="1" accept=".xls,.xlsx,.csv" :on-change="change" style="margin-top:20px"><div style="padding:24px"><b>拖放 XLSX / XLS / CSV 到这里</b><p class="muted">文件不会包含或保存身份证件、地址证明等正式身份资料</p></div></el-upload><div style="margin-top:18px;text-align:right"><el-button type="primary" :loading="loading" @click="preview">解析并预览</el-button></div></div><template v-if="result"><div class="metric-grid section-gap"><div class="metric-card"><div class="metric-label">总行数</div><div class="metric-value">{{result.batch.totalCount}}</div></div><div class="metric-card"><div class="metric-label">唯一匹配</div><div class="metric-value">{{result.matched}}</div></div><div class="metric-card"><div class="metric-label">未匹配 / 多匹配</div><div class="metric-value">{{result.unmatched+result.ambiguous}}</div></div></div><div class="table-card section-gap"><div class="table-toolbar"><span class="table-title">导入预览</span><el-button v-if="result.batch.status==='PREVIEW'" type="primary" @click="confirm">确认导入</el-button><el-tag v-else type="success">已确认</el-tag></div><el-table :data="result.rows"><el-table-column prop="rowNumber" label="行" width="65"/><el-table-column prop="umallOrderNo" label="UMALL订单号" min-width="150"/><el-table-column prop="iccid" label="ICCID" min-width="180"/><el-table-column prop="phone" label="手机号" min-width="125"/><el-table-column prop="planName" label="套餐" min-width="150"/><el-table-column prop="activationStatus" label="激活状态" width="105"/><el-table-column prop="contractStatus" label="合约状态" width="105"/><el-table-column prop="matchMethod" label="匹配方式" width="120"/><el-table-column label="匹配结果" width="120"><template #default="s"><el-tag :type="s.row.matchStatus==='MATCHED'?'success':s.row.matchStatus==='AMBIGUOUS'?'warning':'danger'">{{s.row.matchStatus}}</el-tag></template></el-table-column><el-table-column prop="exceptionReason" label="异常原因" min-width="210"/></el-table></div></template></div></template>
